// Synthetic fixtures are generated by pob-item-affixes-smoke.
const {_electron:electron}=require('playwright'),assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path');
require('tsx/cjs');const {createDefaultState,createBuildDocument}=require('../src/shared/state.ts');
const fixture=JSON.parse(fs.readFileSync('.local/standalone-pob/item-affixes-fixture.json','utf8')),root=path.resolve('.'),directory=path.join(root,'.local','item-affixes-native-'+Date.now()),executable=process.env.POK_SMOKE_EXECUTABLE;
fs.mkdirSync(path.join(directory,'resources'),{recursive:true});for(const name of ['pob-runtime','pob-editor'])fs.symlinkSync(path.join(root,'resources',name),path.join(directory,'resources',name),'junction');
const ranged=createBuildDocument('Synthetic Legacy Range',fixture.xml),crafted=createBuildDocument('Synthetic Crafted Affixes',fixture.craftXml),initial=createDefaultState();initial.builds=[ranged,crafted];initial.activeBuildId=ranged.id;initial.settings.pok.autoConnect=false;fs.mkdirSync(path.join(directory,'workspace'));fs.writeFileSync(path.join(directory,'workspace','workspace.v1.json'),JSON.stringify(initial));
const env={...process.env,POK_UI_DATA_DIR:directory,POK_UI_RESOURCE_DIR:path.join(directory,'resources')};delete env.ELECTRON_RUN_AS_NODE;delete env.POK_RENDERER_URL;
let app,page;const report={at:new Date().toISOString(),passed:[]};const current=()=>page.evaluate(async()=>{const s=await window.pok.loadState();return s.builds.find(b=>b.id===s.activeBuildId);});
async function poll(read,test){const end=Date.now()+120000;let value;do{value=await read();if(test(value))return value;await page.waitForTimeout(200);}while(Date.now()<end);throw new Error('Poll timed out: '+JSON.stringify(value));}
async function launch(){app=await electron.launch({executablePath:executable||path.join(root,'node_modules','electron','dist','electron.exe'),args:executable?[]:[root],cwd:directory,env,timeout:90000});page=await app.firstWindow();page.setDefaultTimeout(90000);await page.locator('.app-shell').waitFor();report.packaged=await app.evaluate(({app})=>app.isPackaged);if(executable)assert(report.packaged);}
async function open(){await page.getByRole('button',{name:'반지 1 슬롯',exact:true}).click();}
async function applied(revision){return poll(current,b=>b.revision===revision&&b.calculation?.revision===revision);}
(async()=>{
  await launch();await open();const range=page.locator('input[type=range][aria-label^="Modifier Range 1"]');await poll(()=>range.isEnabled(),Boolean);await range.focus();await range.press('End');let saved=await applied(1);assert.equal(saved.calculation.result.stats.Dex,fixture.dex.after);assert.match(saved.xml,/id="1" range="1" future="keep"><FutureRange\/>/);assert.equal(saved.originalXml,fixture.xml);
  await page.getByRole('button',{name:'되돌리기',exact:true}).click();saved=await poll(current,b=>b.revision===2);assert.equal(saved.xml,fixture.xml);
  report.passed.push('generic native roll changes preserve future range metadata, update the stored roll, and undo to the exact original');
  await page.getByLabel('현재 빌드',{exact:true}).selectOption(crafted.id);await open();const prefix=page.getByLabel('Prefix: 1',{exact:true});await poll(()=>prefix.isEnabled(),Boolean);await prefix.selectOption({label:fixture.affixOption.label});await applied(1);const slider=page.getByLabel('Affix Tier / Roll 1',{exact:true});await poll(()=>slider.isEnabled(),Boolean);await slider.focus();await slider.press('Home');saved=await applied(2);assert.equal(saved.calculation.result.stats.Life,fixture.life.low);
  report.passed.push('original affix group choice and native minimum tier/roll apply to a fresh calculated revision');
  await poll(()=>page.getByLabel('Affix Tier / Roll 1',{exact:true}).isEnabled(),Boolean);await page.getByLabel('Affix Tier / Roll 1',{exact:true}).focus();await page.getByLabel('Affix Tier / Roll 1',{exact:true}).press('End');await applied(3);
  for(const [width,height]of[[1920,1080],[1024,768]]){await app.evaluate(({BrowserWindow},size)=>BrowserWindow.getAllWindows()[0].setContentSize(...size),[width,height]);await slider.scrollIntoViewIfNeeded();const bounds=await slider.boundingBox();assert(bounds&&bounds.y>=0&&bounds.y+bounds.height<=height);assert(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+1));await page.screenshot({path:path.join(directory,'affixes-'+width+'.png')});}
  saved=await applied(3);assert.equal(saved.calculation.result.stats.Life,fixture.life.high);assert(saved.xml.includes('ModRange'));assert.equal(saved.originalXml,fixture.craftXml);
  report.passed.push('native maximum tier/roll changes real Life without renderer range math and fits both screen sizes');
  await app.close();app=undefined;await launch();assert.equal((await current()).xml,saved.xml);assert.equal((await current()).calculation.revision,3);assert.equal((await page.evaluate(()=>window.pok.getPokConnection())).connected,false);
  report.passed.push('affix/raw/legacy metadata and measured revision survive restart without PoK');
})().catch(async error=>{report.error=error.stack;process.exitCode=1;if(page)await page.screenshot({path:path.join(directory,'failure.png')}).catch(()=>{});}).finally(async()=>{if(app)await app.close();fs.writeFileSync(path.join(directory,'result.json'),JSON.stringify(report,null,2));console.log(directory);if(report.error)console.error(report.error);});
